css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#e6e2d8;color:#263e42;font-family:"Hiragino Maru Gothic ProN","Hiragino Kaku Gothic ProN",Meiryo,sans-serif}nav{max-width:1040px;margin:0 auto;padding:20px 24px;display:flex;gap:22px;align-items:center;font-size:14px}a{color:inherit;text-underline-offset:4px}nav a:last-child{margin-left:auto}.page{width:min(1040px,calc(100% - 32px));min-height:660px;margin:0 auto 28px;padding:46px 58px 34px;background:#fffaf0;display:flex;flex-direction:column;break-after:page;position:relative}.blue{background:#edf5f7}.mint{background:#edf5ed}.rose{background:#faece6}.cover{background:#f4d97d}.tag{font-size:13px;font-weight:700;letter-spacing:2px;margin:0 0 26px}.page h1,.page h2{font-size:36px;line-height:1.6;margin:0 0 20px;font-weight:700;white-space:pre-line}.cover h1{font-size:46px;line-height:1.65}.story{font-size:22px;line-height:2.05;margin:0;white-space:pre-line}.art{display:flex;align-items:center;justify-content:center;gap:76px;flex:1;padding:30px 0 22px;min-height:150px}.art img{width:116px;height:116px;object-fit:contain}.cover .art img{width:144px;height:144px}.caption{font-size:15px;line-height:1.8;margin:0 30px 0 0}.foot{margin-top:auto;padding-top:14px;display:flex;justify-content:space-between;align-items:end}.folio{font-size:13px;white-space:nowrap}ol{font-size:17px;line-height:1.9;padding-left:1.6em;margin:15px 0}li+li{margin-top:8px}.extra .story{font-size:18px;line-height:1.9}.extra .art{min-height:0;padding:12px 0;gap:48px}.extra .art img{width:54px;height:54px}.small{font-size:15px;line-height:1.9;margin:16px 0}.credits{font-size:12px;line-height:1.8}table{border-collapse:collapse;width:100%;font-size:17px;margin:12px 0}th,td{border-bottom:1px solid #789197;text-align:left;padding:13px}th{font-size:14px}footer{padding:20px 30px 40px;text-align:center;font-size:14px}@media(max-width:650px){nav{padding:16px;gap:15px;font-size:12px}.page{padding:28px 24px;min-height:630px;margin-bottom:16px}.tag{font-size:11px;letter-spacing:1px}.page h1,.page h2{font-size:27px}.cover h1{font-size:31px}.story{font-size:18px;line-height:2;white-space:normal}.art{gap:25px}.art img{width:76px;height:76px}.cover .art img{width:84px;height:84px}.caption{font-size:13px}.extra .story{font-size:17px}ol{font-size:16px}.small{font-size:14px}th,td{padding:10px 6px;font-size:14px}}@media print{@page{size:210mm 210mm;margin:0}body{background:white;-webkit-print-color-adjust:exact;print-color-adjust:exact}nav,footer{display:none}.page{width:210mm;height:210mm;min-height:0;margin:0;padding:12mm 14mm 9mm;break-inside:avoid;overflow:hidden}.page:last-child{break-after:auto}.tag{font-size:10px;margin-bottom:18px}.page h1,.page h2{font-size:28px}.cover h1{font-size:38px}.story{font-size:19px}.art img{width:108px;height:108px}.extra .story{font-size:16px}ol{font-size:15px;line-height:1.8}.small{font-size:13px}.credits{font-size:11px}.caption{font-size:12px}table{font-size:15px}th,td{padding:10px}}'''
parts=['<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ぺらぺらの はしと おやつの むこうがわ</title><style>'+css+'</style></head><body><nav aria-label="本の案内"><a href="#p1">表紙</a><a href="#p14">やってみよう</a><a href="book.pdf">PDFを読む</a></nav><main>']
md=['# ぺらぺらの はしと おやつの むこうがわ\n']
for i,p in enumerate(pages,1):
 h='h1' if i==1 else 'h2'
 art=''.join(f'<img src="assets/{a}.png" alt="{names[a]}" width="72" height="72">' for a in p['art'])
 parts.append(f'<section class="page {p["tone"]} {"extra" if "extra" in p else ""}" id="p{i}" aria-labelledby="title{i}"><p class="tag">{escape(p["tag"])}</p><{h} id="title{i}">{escape(p["title"])}</{h}><p class="story">{escape(p["text"])}</p><div class="art">{art}</div>{p.get("extra", "")}<div class="foot"><p class="caption">{escape(p["scene"])}</p><span class="folio">{i:02} / 16</span></div></section>')
 md.append(f'## {i:02}　{p["title"].replace(chr(10), " ")}\n\n{p["text"]}\n\n*{p["scene"]}*\n\n'+p.get('extra','')+'\n')
parts.append('</main><footer><a href="#p1">表紙にもどる</a> · 全16ページ · 画像生成AI不使用</footer></body></html>')
(ROOT/'index.html').write_text(''.join(parts))
(ROOT/'manuscript.md').write_text('\n'.join(md))
print('16 pages written')
